// Batch size is 1, so exactly one lead + one fetched page per run of this node.
const lead = $('Loop Over Leads').first().json;
const res = $input.first().json;

// The HTTP node returns the page body in `data` (responseFormat: text).
// If the fetch failed (onError: continue), there is no body at all.
let raw = '';
if (typeof res.data === 'string') { raw = res.data; }
else if (typeof res.body === 'string') { raw = res.body; }

let title = '';
let metaDesc = '';
let text = '';

if (raw) {
  const t = raw.match(/<title[^>]*>([\s\S]*?)<\/title>/i);
  if (t) { title = t[1].replace(/\s+/g, ' ').trim(); }

  const m = raw.match(/<meta[^>]*name=["']description["'][^>]*content=["']([^"']*)["']/i)
    || raw.match(/<meta[^>]*content=["']([^"']*)["'][^>]*name=["']description["']/i);
  if (m) { metaDesc = m[1].trim(); }

  text = raw
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<noscript[\s\S]*?<\/noscript>/gi, ' ')
    .replace(/<svg[\s\S]*?<\/svg>/gi, ' ')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&[a-zA-Z#0-9]+;/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

// Title + meta description first: usually the densest signal on a homepage.
let combined = [title, metaDesc, text].filter(Boolean).join(' | ').slice(0, 3500);

// If there are fewer than 80 letters of real content, personalization would be
// guesswork -> blank it so the IF node routes this lead to the fallback branch.
if (combined.replace(/[^a-zA-Z]/g, '').length < 80) { combined = ''; }

return [{ json: {
  name: (lead.Name || '').toString().trim(),
  company: (lead.Company || '').toString().trim(),
  website: (lead.Website || '').toString().trim(),
  row_number: lead.row_number,
  website_text: combined
} }];

// Safely parse the model reply. A malformed reply flags the row instead of
// crashing the whole run.
const lead = $('Extract Website Text').first().json;
const res = $input.first().json;

let content = '';
if (res && res.choices && res.choices[0] && res.choices[0].message) {
  content = res.choices[0].message.content || '';
}

// Strip accidental markdown fences, then parse.
content = content.trim().replace(/^```(json)?/i, '').replace(/```$/, '').trim();

let parsed = null;
try {
  parsed = JSON.parse(content);
} catch (e) {
  const m = content.match(/\{[\s\S]*\}/);
  if (m) {
    try { parsed = JSON.parse(m[0]); } catch (e2) { parsed = null; }
  }
}

if (!parsed || !parsed.opener) {
  return [{ json: {
    row_number: lead.row_number,
    opener: '',
    summary: '',
    status: 'AI ERROR - will retry automatically on next run'
  } }];
}

const conf = String(parsed.confidence || 'medium').toLowerCase();

return [{ json: {
  row_number: lead.row_number,
  opener: String(parsed.opener).replace(/\s+/g, ' ').trim(),
  summary: String(parsed.company_summary || '').replace(/\s+/g, ' ').trim(),
  status: conf === 'low' ? 'REVIEW - low confidence' : 'READY'
} }];
